const fs=require('fs'),path=require('path'),crypto=require('crypto');(async()=>{const url='https://rescene.love/media/members/liv.webp',p=path.join(__dirname,'reference_liv_profile_20261102.webp');const r=await fetch(url);if(!r.ok)throw Error('HTTP '+r.status);const b=Buffer.from(await r.arrayBuffer());if(fs.existsSync(p)){if(!fs.readFileSync(p).equals(b))throw Error('existing reference differs');}else fs.writeFileSync(p,b,{flag:'wx'});const receipt={url,discoveryPage:'https://rescene.love/en/members/liv/',attribution:'Fan page labels image as official Runaway profile portrait, copyright THE MUZE Entertainment; mirror, not verified direct official image endpoint.',retrievedAt:new Date().toISOString(),sha256:crypto.createHash('sha256').update(b).digest('hex'),purpose:'User-requested RESCENE LIV facial reference for Spearmage only'};fs.writeFileSync(path.join(__dirname,'reference_liv_profile_20261102.receipt.json'),JSON.stringify(receipt,null,2)+'\n');console.log(JSON.stringify({path:p,bytes:b.length,source:url}));})().catch(e=>{console.error(e);process.exitCode=1;});
